entries[51954] = { ["name"] = "Zügel des blutgebadeten Frostbrutbezwingers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren blutgebadeten Frostbrutbezwinger oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Name \"Blutgebadeter Bezwinger\" wird an jene wiedererweckten Frostwyrm verliehen, die einem besonders grausigen und blutigen Tod erlegen sind.\"\nErfolg:\nRuhm des Schlachtzüglers von Eiskrone (10 Spieler)\nKategorie:\nDungeons & Schlachtzüge" }
entries[51955] = { ["name"] = "Zügel des eisbeschlagenen Frostbrutbezwingers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren eisbeschlagenen Frostbrutbezwinger oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Frostbrutbezwinger, auferstanden aus den eisigen Tiefen von Eiskrone, werden zu den grimmigsten und unerbittlichsten aller Frostwyrm gezählt.\"\nErfolg:\nRuhm des Schlachtzüglers von Eiskrone (25 Spieler)\nKategorie:\nDungeons & Schlachtzüge" }
