entries[52197] = { ["name"] = "Figur - Dämonenpanther", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nBenötigt Juwelierskunst des Kataklysmus\n(25)\n\"Diese winzige Statue wurde schwer beschädigt.\"" }
entries[52198] = { ["name"] = "Frisches Sturmschnauzensteak", ["text"] = "Questgegenstand\nEinzigartig (4)\n\"Ein riesiges Stück Fleisch, das vor Energie knistert.\"" }
entries[52199] = { ["name"] = "Figur - Dämonenpanther", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure kritische Trefferwertung um + 6.\nBenutzen: Erhöht Eure Beweglichkeit 20 Sek. lang um 19 . (2 Min Abklingzeit)\nBenötigt Juwelierskunst des Kataklysmus\n(25)\nVerkaufspreis:" }
entries[52200] = { ["name"] = "Zügel des scharlachroten Todesstreitrosses", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer scharlachrotes Todesstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In der Eiskronenzitadelle untergebracht, um den bevorzugten Schergen des Lichkönigs zu dienen.\"\nQuest:\nZusammenkunft mit Mograine\nZone:\nEiskronenzitadelle" }
entries[52201] = { ["name"] = "Muradins Gunst", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Ihr nehmt 10 Min. lang die Gestalt eines Frostzwergs an. (30 Min Abklingzeit)\n\"Ich werde Euch immer als meinen Bruder betrachten.\"" }
